import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.CCXDMzJr.js";const g=JSON.parse('{"title":"Introducing Slicemeter: eBPF-Powered GPU FinOps for Kubernetes","description":"","frontmatter":{},"headers":[],"relativePath":"blog/introducing-slicemeter.md","filePath":"blog/introducing-slicemeter.md"}'),i={name:"blog/introducing-slicemeter.md"};function r(o,e,l,c,p,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="introducing-slicemeter-ebpf-powered-gpu-finops-for-kubernetes" tabindex="-1">Introducing Slicemeter: eBPF-Powered GPU FinOps for Kubernetes <a class="header-anchor" href="#introducing-slicemeter-ebpf-powered-gpu-finops-for-kubernetes" aria-label="Permalink to &quot;Introducing Slicemeter: eBPF-Powered GPU FinOps for Kubernetes&quot;">​</a></h1><p><em>By Digvijay Chauhan: August 8, 2026</em></p><hr><p>As generative AI workloads explode across enterprise Kubernetes clusters, finance teams face a massive blind spot: <strong>How much is team-nlp actually spending on shared H100/A100 GPU clusters?</strong></p><p>Traditional Kubernetes FinOps tools rely on CPU/RAM metrics or split DCGM utilization evenly across pods. But under GPU time-slicing (where multiple containers share a single physical GPU), these estimates are wildly inaccurate.</p><h2 id="the-slicemeter-solution-native-ebpf-uprobes" tabindex="-1">The Slicemeter Solution: Native eBPF Uprobes <a class="header-anchor" href="#the-slicemeter-solution-native-ebpf-uprobes" aria-label="Permalink to &quot;The Slicemeter Solution: Native eBPF Uprobes&quot;">​</a></h2><p>Slicemeter attaches eBPF uprobes directly to <code>cudaLaunchKernel</code> and <code>cudaMalloc</code> in host <code>libcudart.so</code> libraries:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> </span></span>
<span class="line"><span> HOST LINUX KERNEL &amp; EBPF </span></span>
<span class="line"><span> </span></span>
<span class="line"><span> </span></span>
<span class="line"><span> uprobe/cudaLaunchKernel (Nanosecond Execution Time)</span></span>
<span class="line"><span> uprobe/cudaMalloc (Exact VRAM Allocation Bytes)</span></span>
<span class="line"><span> PID-to-Pod Cgroup Resolver (/proc/&lt;pid&gt;/cgroup)</span></span></code></pre></div><p>By resolving host process IDs to Kubernetes container cgroups in kernel space, Slicemeter delivers <strong>dollar-denominated GPU chargeback without modifying application code</strong>.</p><h2 id="dual-engine-architecture-cloud-saas-vs-enterprise-air-gapped" tabindex="-1">Dual-Engine Architecture: Cloud SaaS vs. Enterprise Air-Gapped <a class="header-anchor" href="#dual-engine-architecture-cloud-saas-vs-enterprise-air-gapped" aria-label="Permalink to &quot;Dual-Engine Architecture: Cloud SaaS vs. Enterprise Air-Gapped&quot;">​</a></h2><ul><li><strong>Cloud SaaS</strong>: Subscribe at <code>slicemeter.com</code>, deploy a lightweight 1-line agent via Helm, and view multi-cluster cost analytics in seconds.</li><li><strong>Enterprise Air-Gapped</strong>: For banks and healthcare organizations running in isolated, air-gapped data centers. Uses offline RSA digital signatures (<code>.lic</code> file) and native OIDC SSO (Azure AD, Keycloak) with <strong>0 external network egress</strong> (Stripe &amp; public endpoints completely compiled out).</li></ul><hr><p>Try Slicemeter today by checking out our <a href="/guide/helm-quickstart.html">Helm Quickstart</a> or inspecting the <a href="/changelog/v1.0.0.html">v1.0.0 Release Notes</a>.</p>`,13)])])}const h=a(i,[["render",r]]);export{g as __pageData,h as default};
